void Solver::rephase() {
    // 1. Reset the rephase counter so we start a fresh counting period.
    rephases = 0;

    // 2. Make the next rephase happen sooner, but keep a lower bound
    //    (so we don't shrink the threshold to an unusably small value).
    //    Reduce by 20% and clamp to at least the number of variables.
    threshold = std::max((int)(threshold * 0.8), vars);

    // 3. Grow the rephase limit adaptively: the more conflicts we have seen,
    //    the larger the limit, giving the solver more time before another
    //    rephase is forced.
    //    Here we add a base increment plus a small term proportional to
    //    the conflict count.
    rephase_limit += 4096 + conflicts / 10;

    // 4. Update the saved phase information.
    //    Keep the majority of variables with their historically best polarity,
    //    flip a fraction, and assign random polarity to the rest.
    for (int i = 1; i <= vars; ++i) {
        int r = rand() % 100;
        if (r < 60) {
            // 60% keep the best known polarity
            saved[i] = local_best[i];
        } else if (r < 80) {
            // 20% invert the best known polarity
            saved[i] = -local_best[i];
        } else {
            // 20% choose a completely random polarity
            saved[i] = (rand() & 1) ? 1 : -1;
        }
    }

    // 5. Backtrack to the root level so the new phase choices take effect
    //    immediately on the next decision round.
    backtrack(0);
}
